import { PASSWORD, USERS, expect, test } from "../../fixtures";

test.describe("AUTH-02 sign in with wrong password", () => {
  test(
    "wrong password is rejected with 401 invalid_credentials",
    { tag: "@AUTH-02" },
    async ({ request }) => {
      // Arrange
      const wrongPassword = "wrong-password";
      expect(wrongPassword).not.toBe(PASSWORD);

      // Act
      const response = await request.post("/api/auth/login", {
        data: { email: USERS.member, password: wrongPassword },
      });

      // Assert
      expect(response.status()).toBe(401);
      const body = await response.json();
      expect(body.error.code).toBe("invalid_credentials");
      expect(body.access_token).toBeUndefined();
    },
  );
});
